1119	// ════════════════════════════════════════════════════════════════════════
1120	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
1121	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
1122	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
1123	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
1124	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
1125	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
1126	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
1127	//
1128	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
1129	//  the contraction length K (T for per-position weights, B for the head).
1130	// ════════════════════════════════════════════════════════════════════════
1131	struct DecDwSpec {
1132	    const __nv_bfloat16* dY;   // [K, Nout]
1133	    const __nv_bfloat16* X;    // [K, Kin]
1134	    int Nout; int Kin; int K;
1135	    int grad_off;              // element offset of this weight in `grad`
1136	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1137	    int bias_off;              // element offset of the bias in `grad`
1138	};
1139	
1140	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
1141	__device__ __forceinline__ void dectc_build_dw_specs(
1142	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
1143	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
1144	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
1145	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
1146	    //   head: out_w=28 (out_b=29)
1147	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
1148	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1149	    for (int s = 0; s < 8; ++s) {
1150	        const int li = s / 4, kind = s % 4;
1151	        DecDwSpec& sp = spec[s];
1152	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1153	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1154	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1155	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1156	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1157	        sp.dY_bias = sp.dY;
1158	    }
1159	    DecDwSpec& hd = spec[8];
1160	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1161	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1162	}
1163	
1164	// Total number of 64×N dW output tiles across the 9 weights (for the tile loop).
1165	template <int N>
1166	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1167	    int n = 0;
1168	    for (int s = 0; s < 9; ++s)
1169	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1170	    return n;
1171	}
1172	
1173	// Run ONE global dW tile `gt` (if it belongs to this CTA): decode (weight, M-atom,
1174	// N-tile), then contract K via the dW GEMM into grad[grad_off]. MaxAtomsM=1.
1175	template <int N>
1176	__device__ __forceinline__ void dectc_dw_run_tile(
1177	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1178	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1179	    // Decode gt → (s, m_atom, n_tile).
1180	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1181	    for (s = 0; s < 9; ++s) {
1182	        const int ma = (spec[s].Nout + 63) / 64;
1183	        const int nt = (spec[s].Kin + N - 1) / N;
1184	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1185	        acc += ma * nt;
1186	    }
1187	    const DecDwSpec& sp = spec[s];
1188	    const int mbase = m_atom * 64;
1189	    const int n0 = n_tile * N;
1190	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1191	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1192	    const int Nout = sp.Nout, Kin = sp.Kin;
1193	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1194	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase, m_atoms=1) passes the
1195	    // GLOBAL row m = mbase + mn to srcA/out (it adds mbase0 itself), so the
1196	    // accessors use `m` RAW — adding mbase again would double-count (the selftest
1197	    // passes mbase0=0 and uses m raw; we pass mbase0=mbase and likewise use m raw).
1198	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1199	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1200	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1201	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1202	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1203	    auto out  = [&] (int m, int n, float v) {
1204	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1205	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1206	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1207	}
1208	
1209	// ════════════════════════════════════════════════════════════════════════
1210	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
1211	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
1212	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
1213	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
1214	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
1215	//  reduce sums the G partials into grad — no float atomics, fixed order, so
1216	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
1217	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
1218	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
1219	//  kc) at dw_part[((gt*G+kc)) * (64*kDecMaxTileN) + row*kDecMaxTileN + col].
1220	//  Decoder K varies per spec: layer dW K=T, head dW K=B (so kc_steps reads sp.K).
1221	// ════════════════════════════════════════════════════════════════════════
1222	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
1223	constexpr int kDecDwTileFloats = wgs::kWgmmaAtomM * kDecMaxTileN;   // 64*N per (gt,kc) slot
1224	
1225	// COMPILE-TIME max #dW output tiles (the 9 dW have fixed Nout/Kin; decoder dims
1226	// are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff×d),
1227	// ff2(d×dff), N=kDecMaxTileN; + head(V×d).
1228	constexpr int kDecDwTilesPerLayer =
1229	      ((3*dec::kD + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
1230	    + ((dec::kD   + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
1231	    + ((dec::kDff + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
1232	    + ((dec::kD   + 63)/64) * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
1233	constexpr int kDecDwHeadTiles =
1234	      ((dec::kVocab + 63)/64) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
1235	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
1236	
1237	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
1238	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
1239	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
1240	}
1241	
1242	// Decode global dW tile index gt → (spec index s, m_atom, n_tile). Single-source.
1243	template <int N>
1244	__device__ __forceinline__ void dectc_dw_decode(
1245	        const DecDwSpec spec[9], int gt, int& s, int& m_atom, int& n_tile) {
1246	    int acc = 0;
1247	    for (s = 0; s < 9; ++s) {
1248	        const int ma = (spec[s].Nout + 63) / 64;
1249	        const int nt = (spec[s].Kin + N - 1) / N;
1250	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; return; }
1251	        acc += ma * nt;
1252	    }
1253	    s = 8; m_atom = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1254	}
1255	
1256	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
1257	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
1258	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
1259	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
1260	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
1261	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
1262	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
1263	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
1264	template <int N>
1265	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
1266	        const DecDwSpec spec[9], int gt, int kc, int G, float* __restrict__ dw_part,
1267	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1268	    int s, m_atom, n_tile;
1269	    dectc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1270	    const DecDwSpec& sp = spec[s];
1271	    const int mbase = m_atom * 64;
1272	    const int n0 = n_tile * N;
1273	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
1274	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
1275	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1276	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
1277	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
1278	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
1279	    // uninitialized accumulator → zero the slot + return instead of running it
1280	    // (the reduce sums all G slots unconditionally, so an empty chunk MUST be 0).
1281	    if (kc_steps <= 0) {
1282	        for (int i = threadIdx.x; i < 64 * N; i += blockDim.x) slot[i] = 0.0f;
1283	        __syncthreads();
1284	        return;
1285	    }
1286	    const int Nout = sp.Nout, Kin = sp.Kin;
1287	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1288	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1289	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1290	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1291	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1292	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it); the slot holds only this
1293	    // atom's 64 LOCAL rows → index by (m - mbase). A `m<64` guard would never fire
1294	    // for m_atom>=1 → that slot stays UNWRITTEN (the rel~1.0 dW bug). Local-row fills it.
1295	    auto out  = [&] (int m, int n, float v) {
1296	        const int lr = m - mbase;
1297	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1298	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1299	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1300	}
1301	
1302	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
1303	// → grad. Same (gt → geometry) decode as the partial.
1304	template <int N>
1305	__device__ __forceinline__ void dectc_dw_reduce_splitk(
1306	        const DecDwSpec spec[9], int n_dw, int G, const float* __restrict__ dw_part,
1307	        float* __restrict__ grad, int cta, int nCTA) {
1308	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1309	        int s, m_atom, n_tile;
1310	        dectc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1311	        const DecDwSpec& sp = spec[s];
1312	        const int mbase = m_atom * 64;
1313	        const int n0 = n_tile * N;
1314	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1315	        const int Nrow = (sp.Nout - mbase) < 64 ? (sp.Nout - mbase) : 64;
1316	        const int64_t base = (int64_t)gt * G * kDecDwTileFloats;
1317	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1318	            const int row = idx / n_real, col = idx % n_real;
1319	            float accv = 0.0f;
1320	            for (int kc = 0; kc < G; ++kc)
1321	                accv += dw_part[base + (int64_t)kc * kDecDwTileFloats + (int64_t)row * N + col];
1322	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1323	        }
1324	    }
1325	}
1326	
1327	// Biases db = Σ_K dY  (column-sum of dY[K,Nout] → [Nout], per output row).
1328	//
1329	// WAS: each CTA strided ALL bias outputs and ran the full Σ_K reduction — i.e. the
1330	// ENTIRE column-sum was recomputed redundantly on ALL ~132 CTAs (the comment called
1331	// it "cheap" — true only when Nout≤3d=384 at the d=128 production width; at the
1332	// d=1024 roofline width Nout reaches 4d=4096 and K=T=65536, so the 132× redundant
1333	// reduction was the DOMINANT grad_asm cost — ~500 ms, eclipsing even the embedding
1334	// scan this task set out to fix; the per-phase profiler (ga.biases sub-timer) made
1335	// it visible). HBM traffic was 132 × Σ_s K_s·Nout_s·2 B ≈ 70 GB.
1336	//
1337	// NOW: SINGLE OWNER per output element across the WHOLE grid. Flatten the 9 specs'
1338	// outputs into one global index space [0, ΣNout) and grid-stride it over all CTAs
1339	// × threads, so each bias output is reduced EXACTLY ONCE and the work is spread
1340	// across the full grid. Traffic collapses to Σ_s K_s·Nout_s·2 B (one pass, ≈ 130×
1341	// less at d=1024). Reads stay COALESCED (consecutive threads → consecutive o on the
1342	// same k → consecutive dY addresses). DETERMINISM: one owner per output + the SAME
1343	// ascending-k fp32 accumulation → bit-identical to the old per-output sum, no atomics.
1344	//
1345	// PORTABLE: the "single-owner grid-stride column-sum" is the general fix for any
1346	// bias/reduction-to-a-vector that a megakernel was recomputing per-CTA; vit/mamba
1347	// bias grads (same db = Σ_K dY shape) reuse this verbatim.
1348	__device__ __forceinline__ void dectc_dw_biases(
1349	        const DecDwSpec spec[9], float* __restrict__ grad, int cta, int nCTA) {
1350	    // exclusive prefix of Nout across the 9 specs → total bias-output count.
1351	    int pre[10];
1352	    pre[0] = 0;
1353	    #pragma unroll
1354	    for (int s = 0; s < 9; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
1355	    const int total = pre[9];
1356	    const int stride = nCTA * blockDim.x;
1357	    for (int go = cta * blockDim.x + threadIdx.x; go < total; go += stride) {
1358	        // decode global output index → (spec s, local row o). 9 specs → linear scan.
1359	        int s = 0;
1360	        #pragma unroll
1361	        for (int t = 0; t < 9; ++t) if (go >= pre[t + 1]) s = t + 1;
1362	        const DecDwSpec& sp = spec[s];
1363	        const int o = go - pre[s];
1364	        float accv = 0.0f;
1365	        for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1366	        grad[sp.bias_off + o] = accv;
1367	    }
1368	}
1369	
1370	// ════════════════════════════════════════════════════════════════════════
1371	//  P2 — EMBEDDING grad (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1372	//
1373	//  WAS (the owner-LINEAR-SCAN, task #13 H2 target): each of V owner-CTAs scanned
1374	//  ALL T tokens (`if tok_ids[t]==r` per token), re-reading the WHOLE dh0 stream V
1375	//  times — O(V·d·T) work + V passes over 134 MB of dh0, where O(d·T) (ONE pass)
1376	//  suffices. V=99<132 left 33 CTAs idle; threads beyond d idled per owner; pos
1377	//  used only S=4 owner-CTAs scanning all T with a t%S branch.
1378	//

1378	//
1379	//  NOW (H2 — counting-sort token lists + flat-element grid-stride):
1380	//    BUILD (dectc_embed_build_lists, once, cta 0, in the P1 window so it overlaps
1381	//    fwd/bwd and adds NO barrier — B1 already fences it before P2 consumes):
1382	//    a deterministic integer counting sort over tok_ids → row_start[V+1] (CSR
1383	//    offsets) + perm[T] (token positions bucketed by vocab row, ASCENDING t
1384	//    within each row, because the scatter visits t ascending and appends).
1385	//    CONSUME (dectc_embed_owner_scan): a flat grid-stride over ALL V·d output
1386	//    elements. Element (r,j) walks ONLY row r's own tokens perm[row_start[r] ..
1387	//    row_start[r+1]) in ascending-t order, reading dh0[perm[i]·d + j]. Total
1388	//    work collapses to O(d·T) (each dh0 value read once in aggregate); reads are
1389	//    COALESCED (consecutive threads = consecutive j on the same token row); ALL
1390	//    132 CTAs + full blockDim are busy (V·d=101376 elems ≫ 132·256). pos is the
1391	//    same flat grid-stride but needs NO list: tokens with (t%S)==p are exactly
1392	//    t = p, p+S, …, p+(B-1)·S (T=B·S), a closed-form ascending walk of length B.
1393	//
1394	//  DETERMINISM: per row the accumulation order over its tokens is the SAME fixed
1395	//  ascending-t order as the old scan (perm is built ascending; pos walk is
1396	//  ascending) → bitwise-identical fp32 accumulation, no float atomics, no timing-
1397	//  dependent order. The build is integer-exact (histogram counts + prefix +
1398	//  serial ascending scatter), so row_start/perm are bit-identical every rerun.
1399	//
1400	//  PORTABLE: this CSR-bucket + flat-element grid-stride is the general pattern for
1401	//  any "gather grad into a small set of embedding/lookup rows" — vit patch-proj /
1402	//  pos-embed rows and mamba's embedding will reuse dectc_embed_build_lists +
1403	//  this consume verbatim (only the row count V and the membership map differ; a
1404	//  structural map like pos needs no list at all).
1405	// ════════════════════════════════════════════════════════════════════════
1406	
1407	// Scratch float count for the embedding token lists (host carves it from the
1408	// workspace tail). row_start[V+1] + perm[T], stored as int32 (1 float slot each).
1409	__host__ __device__ __forceinline__ int64_t dec_embed_lists_floats(int T) {
1410	    return (int64_t)(dec::kVocab + 1) + (int64_t)T;
1411	}
1412	
1413	// BUILD the per-vocab-row token lists (counting sort). Single CTA (caller guards
1414	// cta==0); runs in the P1 window so it overlaps fwd/bwd and the existing B1
1415	// barrier fences it before the P2 consume — NO new barrier. `row_start` is
1416	// [V+1] int32 (CSR offsets), `perm` is [T] int32 (token positions, ascending t
1417	// within each vocab-row bucket). All integer ops → bit-exact + deterministic.
1418	//
1419	// COST: O(T), PARALLEL over kW worker lanes (HBM-latency hidden) so the build is a
1420	// few hundred µs — far below the consume saving it enables. DETERMINISM via a fixed
1421	// STRUCTURAL decomposition: worker w owns the CONTIGUOUS t-chunk [w·C,(w+1)·C); it
1422	// histograms then scatters its chunk in ascending t into a per-(worker,row) slice
1423	// of perm whose base sits AFTER all lower-w workers' slices for the same row. Lower
1424	// w ⇒ lower t, and within a worker ascending t ⇒ each row's perm bucket is GLOBALLY
1425	// ascending t — the SAME order the old single-cursor scatter (and the old owner-scan
1426	// accumulation) produced, so bit-identical. All integer ops; no atomics on the hot
1427	// path. tok_ids is HBM int32 [T]. row_start is [V+1] (CSR offsets); perm is [T].
1428	__device__ __forceinline__ void dectc_embed_build_lists(
1429	        const int* __restrict__ tok_ids, int T,
1430	        int* __restrict__ row_start, int* __restrict__ perm) {
