1432	    __shared__ int wcnt[kW * dec::kVocab];         // per-(worker,row) count, then base cursor
1433	    // floor-balanced contiguous t-chunk per worker w: [c0(w), c0(w+1)).
1434	    auto c0 = [&] (int w) -> int { return (int)(((int64_t)w * T) / kW); };
1435	    // 1) zero the per-worker histograms (all threads).
1436	    for (int i = threadIdx.x; i < kW * dec::kVocab; i += blockDim.x) wcnt[i] = 0;
1437	    __syncthreads();
1438	    // 2) each of the first kW threads histograms its contiguous t-chunk into its own
1439	    //    row of wcnt (no atomics — private per worker).
1440	    if (threadIdx.x < kW) {
1441	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
1442	        int* my = wcnt + (int64_t)w * dec::kVocab;
1443	        for (int t = e0; t < e1; ++t) {
1444	            const int r = tok_ids[t];
1445	            if (r >= 0 && r < dec::kVocab) my[r]++;
