1453	        for (int r = 0; r < dec::kVocab; ++r) {
1454	            row_start[r] = acc;
1455	            for (int w = 0; w < kW; ++w) acc += wcnt[(int64_t)w * dec::kVocab + r];
1456	        }
1457	        row_start[dec::kVocab] = acc;   // == #tokens with a valid row (≤ T)
1458	    }
1459	    __syncthreads();
1460	    // 4) per-(worker,row) base cursor: wcnt[w][r] ← row_start[r] + Σ_{w'<w} cnt[w'][r]
