1462	    //    thread per row (V≤256 → fits blockDim) scans workers ascending.
1463	    if (threadIdx.x < dec::kVocab) {
1464	        const int r = threadIdx.x;
1465	        int base = row_start[r];
1466	        for (int w = 0; w < kW; ++w) {
1467	            int* slot = &wcnt[(int64_t)w * dec::kVocab + r];
1468	            const int c = *slot;
1469	            *slot = base;        // becomes the live append cursor for (w,r)
1470	            base += c;
1471	        }
1472	    }
1473	    __syncthreads();
1474	    // 5) scatter: each worker walks its chunk ascending t, appending t to perm at
1475	    //    its per-row cursor. Ascending t within the chunk + ascending-worker bases
1476	    //    ⇒ globally ascending t per row bucket.
1477	    if (threadIdx.x < kW) {
1478	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
1479	        int* cur = wcnt + (int64_t)w * dec::kVocab;
1480	        for (int t = e0; t < e1; ++t) {
1481	            const int r = tok_ids[t];
1482	            if (r >= 0 && r < dec::kVocab) perm[cur[r]++] = t;
1483	        }
