1489	// stride over V·d (tok) and S·d (pos) output elements → all CTAs + threads busy,
1490	// coalesced dh0 reads, fixed ascending-t accumulation per row (deterministic).
1491	__device__ __forceinline__ void dectc_embed_owner_scan(
1492	        const DecActs& acts, const int* __restrict__ row_start,
1493	        const int* __restrict__ perm, int T,
1494	        float* __restrict__ grad, int cta, int nCTA) {
1495	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1496	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1497	    const __nv_bfloat16* __restrict__ dh0 = acts.dh0;
1498	    const int stride = nCTA * blockDim.x;
1499	    const int base   = cta * blockDim.x + threadIdx.x;
1500	    // ── tok grad: element (r,j) over V·d, grid-strided. Walk ONLY row r's tokens
1501	    //    (perm[row_start[r] .. row_start[r+1])) ascending → coalesced dh0 column
1502	    //    read across the warp (consecutive j on one token row). ──
1503	    const int64_t Vd = (int64_t)dec::kVocab * dec::kD;
1504	    for (int64_t e = base; e < Vd; e += stride) {
1505	        const int r = (int)(e / dec::kD);
1506	        const int j = (int)(e - (int64_t)r * dec::kD);
1507	        const int s0 = row_start[r], s1 = row_start[r + 1];
1508	        float accv = 0.0f;
1509	        for (int i = s0; i < s1; ++i)
1510	            accv += __bfloat162float(dh0[(int64_t)perm[i] * dec::kD + j]);
1511	        grad[tok_off + e] = accv;
1512	    }
1513	    // ── pos grad: element (p,j) over S·d, grid-strided. Tokens with (t%S)==p are
1514	    //    t = p, p+S, …, p+(B-1)·S (T=B·S) — closed-form ascending walk, no list. ──
1515	    const int64_t Sd = (int64_t)dec::kSeq * dec::kD;
1516	    const int B = T / dec::kSeq;
1517	    for (int64_t e = base; e < Sd; e += stride) {
1518	        const int p = (int)(e / dec::kD);
1519	        const int j = (int)(e - (int64_t)p * dec::kD);
1520	        float accv = 0.0f;
1521	        int t = p;
1522	        for (int i = 0; i < B; ++i, t += dec::kSeq)
1523	            accv += __bfloat162float(dh0[(int64_t)t * dec::kD + j]);
1524	        grad[pos_off + e] = accv;
1525	    }
