1533	// ════════════════════════════════════════════════════════════════════════
1534	__device__ __forceinline__ void dectc_lnvec_reduce(
1535	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1536	        int nCTA, int cta) {
